inline DWORD eqRoot(DWORD pid,std::wstring const& path){HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snapshot==INVALID_HANDLE_VALUE)return pid;std::map<DWORD,DWORD> parents;PROCESSENTRY32W p{sizeof(p)};if(Process32FirstW(snapshot,&p))do{parents[p.th32ProcessID]=p.th32ParentProcessID;}while(Process32NextW(snapshot,&p));CloseHandle(snapshot);for(int i=0;i<32;i++){auto found=parents.find(pid);if(found==parents.end()||!found->second||found->second==pid||eqUpper(processPath(found->second))!=eqUpper(path))break;pid=found->second;}return pid;}
inline bool virtualAudioName(std::wstring name){name=eqUpper(name);std::wstring compact;for(auto c:name)if(iswalnum(c))compact+=c;if(compact.find(L"CABLEIN16CH")!=std::wstring::npos||compact.find(L"VBAUDIOVIRTUALCABLE")!=std::wstring::npos)return true;return name.find(L"虚拟音频节点 (H HUB)")!=std::wstring::npos||name.find(L"H HUB AUDIO")!=std::wstring::npos||name.find(L"HHUB AUDIO")!=std::wstring::npos||name.find(L"FXSOUND AUDIO ENHANCER")!=std::wstring::npos||name.find(L"CABLE INPUT")!=std::wstring::npos||name.find(L"CABLE IN 16 CH")!=std::wstring::npos||name.find(L"VB-AUDIO VIRTUAL CABLE")!=std::wstring::npos||name.find(L"VOICEMEETER INPUT")!=std::wstring::npos;}
