inline void recoverEqRoute(DWORD pid,std::wstring const& path){auto folder=dataDir()/L"eq-routes";if(!std::filesystem::exists(folder))return;auto policy=eqPolicy();for(auto const& file:std::filesystem::directory_iterator(folder)){if(file.path().extension()!=L".json")continue;try{auto saved=object(read(file.path()));if(audioRouteHasLiveOwner(saved))continue;if(eqUpper(str(saved,L"path"))!=eqUpper(path))continue;auto before=saved.GetNamedArray(L"before");if(before.Size()!=3)continue;auto source=L"\\\\?\\SWD#MMDEVAPI#"+str(saved,L"source")+L"#{e6327cad-dcec-4949-ae8a-991e976a79d2}";bool ok=true;for(int role=0;role<3;role++){HSTRING current{};auto hr=policy->GetPersistedDefaultAudioEndpoint(pid,eRender,(ERole)role,&current);std::wstring value;if(current){UINT n{};value=WindowsGetStringRawBuffer(current,&n);WindowsDeleteString(current);}if(FAILED(hr)){ok=false;continue;}if(eqUpper(value)==eqUpper(source)){winrt::hstring original{before.GetStringAt(role)};if(FAILED(policy->SetPersistedDefaultAudioEndpoint(pid,eRender,(ERole)role,original.empty()?nullptr:static_cast<HSTRING>(winrt::get_abi(original))))||!routeMatches(policy.get(),pid,(ERole)role,std::wstring(original)))ok=false;}}if(ok){std::error_code ec;std::filesystem::remove(file.path(),ec);}}catch(...) {}}}
