 void start(JsonObject config){requireSharedAudioAvailable();fxEffectValues(config);auto d=eqDevices();if(!flag(d,L"routingAvailable"))throw hresult_error(E_NOTIMPL,L"当前 Windows 不支持应用路由，请勿启用真实 EQ");if(d.GetNamedArray(L"sources").Size()==0)throw hresult_error(E_NOTIMPL,flag(d,L"driverInstalled")?L"驱动已安装，但当前会话无法访问其音频端点":L"缺少虚拟音频端点，需先安装路由驱动");find(d.GetNamedArray(L"sources"),str(config,L"source"));find(d.GetNamedArray(L"outputs"),str(config,L"output"));std::array<double,12> gains{};auto bands=config.GetNamedArray(L"bands");if(bands.Size()!=12)throw hresult_invalid_argument();for(int i=0;i<12;i++)gains[i]=bands.GetNumberAt(i);EqDsp::validate(gains,num(config,L"preamp"));std::array<double,12> centers{};auto freqs=config.GetNamedArray(L"frequencies");if(freqs.Size()!=12)throw hresult_invalid_argument();for(int i=0;i<12;i++)centers[i]=freqs.GetNumberAt(i);EqDsp::validateFrequencies(centers);auto key=str(config,L"app");if(key==eqAppId((binaryDir()/L"Hhub.exe").wstring())||key==eqAppId((binaryDir()/L"core"/L"Hhub.exe").wstring()))throw hresult_invalid_argument(L"不能处理 H hub 自身，避免音频反馈");for(auto const& active:d.GetNamedArray(L"apps")){auto app=active.GetObject();if(str(app,L"id")==key&&app.GetNamedArray(L"pids",JsonArray{}).Size()>1)throw hresult_error(E_NOTIMPL,L"当前请为同一 EXE 保留一个独立实例");if(str(app,L"id")==key&&app.GetNamedArray(L"activeOutputs",JsonArray{}).Size()>1&&!eqApplicationUsesOutput(app,str(config,L"output"),str(config,L"source")))throw hresult_error(E_NOTIMPL,L"该应用正在使用多个不同输出，为避免影响其他设备，未启用 EQ");}if(streams.find(key)!=streams.end()&&streams.at(key)->sameRoute(config))streams.at(key)->update(config);else{streams.erase(key);streams.emplace(key,std::make_unique<EqStream>(config));}}
